function renderCalendarSummary(posts){const p=visiblePeriod(),summary=periodSummary(posts,dateKey(p.start),dateKey(p.end));return `<div class="calendar-brief"><div><span class="calendar-caption">Dein Redaktionsplan</span><p><strong>${summary.count} ${summary.count===1?'Beitrag':'Beiträge'}</strong> · ${summary.days} ${summary.days===1?'Tag':'Tage'} belegt · ${summary.channels} ${summary.channels===1?'Kanal':'Kanäle'}</p></div><span class="calendar-safe">${icon('shield')}Nur geplant. Nichts wird automatisch veröffentlicht.</span></div>`}
