function postCard(post){return `<button class="post-card" data-post-id="${esc(post.id)}" aria-label="${esc(displayTitle(post))}, ${post.status==='draft'?'Entwurf':`geplant ${shownTime(post)?.local.slice(11,16)} Uhr, ${currentZone()}`}${esc(postLabelDescription(post))}"><div class="post-card-head"><span class="post-time" title="${esc(currentZone())}">${icon(post.status==='draft'?'file':'clock')}${post.status==='draft'?'Entwurf':esc(shownTime(post)?.local.slice(11,16))}</span>${stack(post.channels)}</div>${cover(post)}<p class="post-card-text">${esc(channel==='all'?post.text:effectiveText(post,channel))}</p>${calendarContext(post)}${postLabels(post)}<div class="post-card-footer">${badge(post)}${variantCount(post)?`<span class="variant-count" title="${variantCount(post)} individuelle Kanaltexte">${icon('layers')}${variantCount(post)}</span>`:''}${post.status==='draft'?'<span class="draft-continue">Weiterbearbeiten →</span>':'<span aria-hidden="true">•••</span>'}</div></button>`}
function relevantPosts(){return calendarPosts(filterPosts(state.posts,{channel,query,tag:postTag,status:view==='drafts'?'draft':'scheduled'}),currentZone()).filter(p=>view==='drafts'||calendarStatus==='all'||planningStatus(p,{needsReview:scheduleNeedsReview(p)}).kind===calendarStatus)}
function visiblePeriod(){if(range==='month'){const start=new Date(anchor.getFullYear(),anchor.getMonth(),1);return {start,end:new Date(anchor.getFullYear(),anchor.getMonth()+1,0)}}return {start:startOfWeek(anchor),end:addDays(startOfWeek(anchor),6)}}
