function emptyState(title,description,action='new-post',label='Beitrag erstellen'){return `<div class="empty-state"><div class="empty-icon">${icon(query||channel!=='all'||postTag!==''||((view==='calendar'||view==='list')&&calendarStatus!=='all')?'search':'sparkles')}</div><h3>${title}</h3><p>${description}</p><button class="button primary" data-action="${action}">${icon('plus')}${label}</button></div>`}
function renderWeek(posts){const start=startOfWeek(anchor);const today=dateKey(zonedNow(currentZone()));const cols=Array.from({length:7},(_,i)=>{const day=addDays(start,i),key=dateKey(day);const selected=posts.filter(p=>p.calendarTime?.local.startsWith(key));return `<section class="day-column ${i>4?'weekend':''} ${key===today?'is-today':''}" aria-label="${dateLabel(day,{weekday:'long',day:'numeric',month:'long'})}"><div class="day-heading"><span class="day-name">${days[i].slice(0,2).toUpperCase()}</span><span class="day-number">${day.getDate()}</span></div><div class="day-cards">${selected.map(postCard).join('')}<button class="add-day ${!selected.length?'empty-day':''}" data-new-date="${key}" aria-label="Beitrag für ${dateLabel(day,{day:'numeric',month:'long'})} erstellen">${icon('plus')}${!selected.length?'<span>Beitrag planen</span>':''}</button></div></section>`}).join('');return `<div class="week-grid desktop-week">${cols}</div><div class="mobile-agenda">${renderMobileWeek(periodPosts(posts),start)}</div>`}
function renderMobileWeek(posts,start){return Array.from({length:7},(_,i)=>{const day=addDays(start,i),key=dateKey(day),entries=posts.filter(p=>p.calendarTime?.local.startsWith(key));return `<section class="mobile-plan-day"><div class="mobile-plan-heading"><h3>${dateLabel(day,{weekday:'short',day:'numeric',month:'short'})}${key===dateKey(zonedNow(currentZone()))?' <span>Heute</span>':''}</h3><button class="icon-button" data-new-date="${key}" aria-label="Beitrag für ${dateLabel(day,{day:'numeric',month:'long'})} erstellen">${icon('plus')}</button></div>${entries.length?entries.map(postCard).join(''):'<p class="mobile-open-day">Noch frei für deine Ideen</p>'}</section>`}).join('')}
function renderMonth(posts){const monthStart=new Date(anchor.getFullYear(),anchor.getMonth(),1),start=startOfWeek(monthStart);const monthEnd=new Date(anchor.getFullYear(),anchor.getMonth()+1,0);const cells=Math.ceil((((monthStart.getDay()+6)%7)+monthEnd.getDate())/7)*7;const today=dateKey(zonedNow(currentZone()));return `<div class="desktop-month"><div class="month-grid" aria-label="Monatsübersicht">${days.map(d=>`<div class="month-weekday">${d.slice(0,2)}</div>`).join('')}${Array.from({length:cells},(_,i)=>{const day=addDays(start,i),key=dateKey(day),entries=posts.filter(p=>p.calendarTime?.local.startsWith(key));return `<section class="month-cell ${day.getMonth()!==anchor.getMonth()?'muted':''} ${key===today?'is-today':''}" aria-label="${dateLabel(day,{day:'numeric',month:'long'})}"><span class="month-day-number">${day.getDate()}</span><button class="icon-button month-add" data-new-date="${key}" aria-label="Beitrag für ${dateLabel(day,{day:'numeric',month:'long'})} erstellen">${icon('plus')}</button>${entries.map(p=>`<button class="month-post" data-post-id="${esc(p.id)}" aria-label="${esc(displayTitle(p))}, ${esc(p.calendarTime.local.slice(11,16))} Uhr ${esc(currentZone())}, ${planningStatus(p,{needsReview:scheduleNeedsReview(p)}).label}${esc(postLabelDescription(p))}" title="${esc(displayTitle(p))} · ${planningStatus(p,{needsReview:scheduleNeedsReview(p)}).label}">${scheduleNeedsReview(p)?'<span class="schedule-review-badge" aria-label="Termin prüfen">!</span>':''}${platform(p.channels[0],'tiny')}<span>${esc(p.calendarTime.local.slice(11,16))} ${esc(displayTitle(p))}</span></button>`).join('')}</section>`}).join('')}</div></div><div class="mobile-month">${renderAgenda(periodPosts(posts),true)}<button class="button subtle" data-action="new-post">${icon('plus')}Beitrag einplanen</button></div>`}
function renderAgenda(posts,mobile=false){if(!posts.length)return emptyState(query||channel!=='all'||postTag!==''||((view==='calendar'||view==='list')&&calendarStatus!=='all')?'Keine passenden Beiträge':'Ein frischer Platz für deine Ideen.',query||channel!=='all'||postTag!==''||((view==='calendar'||view==='list')&&calendarStatus!=='all')?'Versuche einen anderen Suchbegriff oder zeige alle Kanäle an.':'Für diesen Zeitraum ist noch nichts geplant. Lege deinen ersten Beitrag an.',query||channel!=='all'||postTag!==''||((view==='calendar'||view==='list')&&calendarStatus!=='all')?'clear-filters':'new-post',query||channel!=='all'||postTag!==''||((view==='calendar'||view==='list')&&calendarStatus!=='all')?'Filter zurücksetzen':'Beitrag erstellen');const grouped=new Map();posts.forEach(p=>{const key=p.calendarTime.local.slice(0,10);grouped.has(key)?grouped.get(key).push(p):grouped.set(key,[p])});return `<div class="agenda-list">${[...grouped].map(([key,entries])=>`<h3 class="agenda-day">${dateLabel(new Date(`${key}T12:00`),{weekday:'long',day:'numeric',month:'long'})}<span>${entries.length} ${entries.length===1?'Beitrag':'Beiträge'}</span></h3>${entries.map(p=>`<button class="agenda-post" data-post-id="${esc(p.id)}" aria-label="${esc(displayTitle(p))}, ${esc(p.calendarTime.local.slice(11,16))} Uhr, ${esc(currentZone())}${esc(postLabelDescription(p))}"><span class="agenda-time">${esc(p.calendarTime.local.slice(11,16))}</span>${cover(p,'agenda-cover')}<div class="agenda-body"><strong>${esc(displayTitle(p))}</strong><p>${esc(p.channels.map(id=>CHANNELS.find(c=>c.id===id)?.name).join(' · '))} · ${esc(currentZone())}</p>${calendarContext(p)}${postLabels(p)}</div>${stack(p.channels)}${badge(p)}${icon('chevron-right')}</button>`).join('')}`).join('')}</div>`}
function ideaEditorSnapshot(){return JSON.stringify({title:$('#idea-title').value,text:$('#idea-text').value,tags:$('#idea-tags').value})}
